WITH base AS (SELECT *, ADD_MONTHS(order_date, 3) AS order_date_plus_months, ROUND(shipping_fee, 2) AS shipping_fee_rounded, COALESCE(channel, 'N/A') AS channel_filled FROM orders WHERE customer_id IS NOT NULL AND channel IS DISTINCT FROM 'mobile') SELECT * FROM (SELECT channel, customer_id, status, shipping_fee FROM base) src PIVOT (MAX(shipping_fee) AS amount, COUNT(1) AS cnt FOR status IN ('PENDING', 'CANCELLED', 'SHIPPED'))
